BEGIN;

DELETE FROM public.compute_insight_gpu_provider_series_daily
WHERE source_label = 'GPU INDEX'
  AND provider_id = 'silicondata'
  AND billing_type = 'ON_DEMAND'
  AND term_months = 0
  AND gpu_model_code IN ('B200','B300','H200')
  AND price_date BETWEEN '2025-08-01' AND '2026-11-10';



COMMIT;
